package com.ds.goroute.repository.impl;import com.ds.goroute.entity.MarketplaceReviewView;import com.ds.goroute.mapper.MarketplaceReviewResponseMapper;import com.ds.goroute.repository.MarketplaceReviewResponseRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Repository;import java.time.LocalDateTime;import java.util.*;
@Repository @RequiredArgsConstructor public class MarketplaceReviewResponseRepositoryImpl implements MarketplaceReviewResponseRepository {private final MarketplaceReviewResponseMapper m;public Optional<MarketplaceReviewView> find(UUID r,UUID o){return Optional.ofNullable(m.findReview(r,o));}public List<MarketplaceReviewView> findByOrganization(UUID o,int l,int f){return m.findByOrganization(o,l,f);}public List<MarketplaceReviewView> findAdmin(String q,int l,int o){return m.findAdmin(q,l,o);}public int insert(UUID id,UUID r,UUID o,UUID a,String t,String s,LocalDateTime n){return m.insertResponse(id,r,o,a,t,s,n);}public int update(UUID r,UUID o,long v,UUID a,String t,String s,LocalDateTime n){return m.updateResponse(r,o,v,a,t,s,n);}}
